// One item per entity x month to (re)load.
// Reads n8n env vars (requires N8N_BLOCK_ENV_ACCESS_IN_NODE=false, see README).
const entities = JSON.parse($env.AUTOCOUNT_CLOUD_ENTITIES || '[]');
if (!entities.length) throw new Error('AUTOCOUNT_CLOUD_ENTITIES is empty');
const lookback = parseInt($env.AUTOCOUNT_CLOUD_LOOKBACK_MONTHS || '2', 10);

// "today" in Kuala Lumpur regardless of the host timezone
const kl = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Kuala_Lumpur' }));
const pad = (n) => String(n).padStart(2, '0');
const iso = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const yesterday = new Date(kl); yesterday.setDate(kl.getDate() - 1);

const out = [];
for (const e of entities) {
  if (!e.entity_code || !e.company_ref) throw new Error('each entity needs entity_code and company_ref');
  for (let n = lookback; n >= 0; n--) {          // oldest first; open months get restated nightly
    const start = new Date(kl.getFullYear(), kl.getMonth() - n, 1);
    const end = new Date(kl.getFullYear(), kl.getMonth() - n + 1, 0);
    out.push({ json: {
      entity_code: e.entity_code,
      company_ref: e.company_ref,               // AutoCount Cloud company / account book id
      period_start: iso(start),
      period_end: iso(end),
      is_latest_month: n === 0,                 // aging is only pulled once per entity (latest month item)
      as_of_date: iso(yesterday),
    }});
  }
}
return out;

parameters.query:
insert into public.ingestion_runs (source, entity_id, dataset, triggered_by, metadata)
values ('autocount_cloud', (select id from public.entities where code = $1), $2, 'schedule', $3::jsonb)
returning id;

