// Maps AutoCount Cloud API responses to warehouse rows.
// ============================================================================
// TODO-VERIFY: every property name in F below is a PLACEHOLDER. No public
// AutoCount Cloud Accounting API documentation was found; set these from the
// vendor's docs / a sample response before enabling the workflow.
// ============================================================================
const cfg = $('Load entity config').item.json;
const runId = $('Start ingestion run').item.json.id;
const tbResp = $('Fetch trial balance').item.json;
let arResp = null, apResp = null;
if (cfg.is_latest_month) {
  try { arResp = $('Fetch debtor aging').item.json; apResp = $('Fetch creditor aging').item.json; }
  catch (e) { /* aging branch did not run for this item */ }
}

const F = {
  rows: 'data',                                   // TODO-VERIFY: property holding the array ('' if the body itself is the array)
  tb: {                                           // TODO-VERIFY: trial balance / GL balance row fields
    accountCode: 'accountCode', accountName: 'accountName', accountType: 'accountType',
    parent: 'parentAccountCode', debit: 'debit', credit: 'credit', closing: 'closingBalance',
    // closingBalance is expected debit-positive and, for P&L accounts, fiscal-year-to-date.
    // If the API returns separate closingDebit/closingCredit, compute closing = closingDebit - closingCredit here.
  },
  aging: {                                        // TODO-VERIFY: debtor/creditor aging row fields
    debtorCode: 'debtorCode', creditorCode: 'creditorCode', name: 'companyName', currency: 'currency',
    current: 'current', b30: 'days1to30', b60: 'days31to60', b90: 'days61to90', b120: 'days91plus',
  },
};

const rowsOf = (resp) => {
  if (!resp) return [];
  const r = F.rows ? resp[F.rows] : resp;
  if (!Array.isArray(r)) throw new Error(`unexpected response shape: expected an array at '${F.rows}'. Keys: ${Object.keys(resp).join(',')}`);
  return r;
};
const num = (v) => {
  const n = Number(String(v ?? 0).replace(/,/g, ''));
  if (Number.isNaN(n)) throw new Error(`not a number: ${v}`);
  return Math.round(n * 100) / 100;
};

// AutoCount account type -> dashboard classification. Keep in sync with
// ACCTYPE_MAP in ../autocount-onprem/extract.py. TODO-VERIFY the labels.
// [account_type, account_subtype, cashflow_bucket, is_current]
const ACCTYPE_MAP = {
  'bank': ['asset', 'cash', 'cash', true], 'cash': ['asset', 'cash', 'cash', true],
  'debtor control': ['asset', 'trade_receivable', 'operating', true],
  'current asset': ['asset', null, 'operating', true], 'stock': ['asset', 'inventory', 'operating', true],
  'deposit': ['asset', 'other_receivable', 'operating', true],
  'fixed asset': ['asset', 'fixed_asset', 'investing', false], 'accumulated depreciation': ['asset', 'fixed_asset', 'investing', false],
  'investment': ['asset', null, 'investing', false], 'other asset': ['asset', null, 'investing', false],
  'creditor control': ['liability', 'trade_payable', 'operating', true],
  'current liability': ['liability', null, 'operating', true],
  'long term liability': ['liability', 'borrowing', 'financing', false],
  'capital': ['equity', 'share_capital', 'financing', null], 'reserves': ['equity', 'retained_earnings', 'financing', null],
  'retained earning': ['equity', 'retained_earnings', 'financing', null],
  'sales': ['revenue', null, 'operating', null], 'sales adjustment': ['revenue', null, 'operating', null],
  'cost of goods sold': ['cogs', null, 'operating', null], 'expenses': ['opex', null, 'operating', null],
  'other income': ['other', null, 'operating', null], 'taxation': ['other', 'tax', 'operating', null],
  'extraordinary income/expense': ['other', null, 'operating', null],
};
const classify = (raw, name) => {
  let [account_type, account_subtype, cashflow_bucket, is_current] =
    ACCTYPE_MAP[String(raw ?? '').trim().toLowerCase()] ?? ['other', null, 'operating', null];
  const n = name.toLowerCase();
  if (account_type === 'opex') {
    if (n.includes('depreciation')) { account_subtype = 'depreciation'; cashflow_bucket = 'non_cash'; }
    else if (n.includes('amortis') || n.includes('amortiz')) { account_subtype = 'amortisation'; cashflow_bucket = 'non_cash'; }
  } else if (account_type === 'other') {
    if (n.includes('interest')) { account_subtype = 'interest'; cashflow_bucket = 'financing'; }
    else if (n.includes('tax') && !n.includes('deferred')) account_subtype = 'tax';
  } else if (account_type === 'liability' && !account_subtype) {
    if (n.includes('accrual')) account_subtype = 'accrual';
    else if (n.includes('tax') || n.includes('sst') || n.includes('cp204')) account_subtype = 'tax_payable';
    else if (n.includes('loan') || n.includes('hire purchase') || n.includes('financing')) account_subtype = 'borrowing';
  }
  return { account_type, account_subtype, cashflow_bucket, is_current };
};

const coa = [], gl = [];
for (const r of rowsOf(tbResp)) {
  const code = String(r[F.tb.accountCode] ?? '').trim();
  if (!code) continue;
  const name = String(r[F.tb.accountName] ?? code);
  coa.push({
    entity_code: cfg.entity_code, account_code: code, name, ...classify(r[F.tb.accountType], name),
    parent_account_code: r[F.tb.parent] ? String(r[F.tb.parent]) : null,
    source_account_type: r[F.tb.accountType] ?? null, is_active: true,
  });
  gl.push({
    entity_code: cfg.entity_code, period_start: cfg.period_start, account_code: code,
    debit: num(r[F.tb.debit]), credit: num(r[F.tb.credit]), closing_balance: num(r[F.tb.closing]),
  });
}
const aging = (resp, codeField) => rowsOf(resp).map((r) => ({
  entity_code: cfg.entity_code, as_of_date: cfg.as_of_date,
  counterparty_code: String(r[codeField] ?? '').trim(),
  counterparty_name: String(r[F.aging.name] ?? r[codeField]),   // business name only (no contact persons)
  currency: r[F.aging.currency] ?? 'MYR',
  bucket_current: num(r[F.aging.current]), bucket_30: num(r[F.aging.b30]), bucket_60: num(r[F.aging.b60]),
  bucket_90: num(r[F.aging.b90]), bucket_120_plus: num(r[F.aging.b120]),
})).filter((x) => x.counterparty_code);

const ar = aging(arResp, F.aging.debtorCode);
const ap = aging(apResp, F.aging.creditorCode);
const tbNet = Math.round(gl.reduce((s, x) => s + x.debit - x.credit, 0) * 100) / 100;  // must be 0.00

return { json: {
  entity_code: cfg.entity_code, run_id: runId,
  periods: [{ entity_code: cfg.entity_code, period_start: cfg.period_start, period_end: cfg.period_end }],
  coa, gl, ar, ap,
  tb_net: tbNet,
  rows_extracted: gl.length + ar.length + ap.length,
} };
